result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "cents_ledger.py", "content": """"Ledger storing amounts as integer cents.

Rule: amounts are parsed from strings via Decimal and converted to
integer cents. Decimal is never constructed from a float, so no binary
floating-point representation error can enter the books.
"""
from decimal import Decimal, InvalidOperation

_SCALE = 100


def parse_cents(amount):
    """Parse an amount given as a string (or int) into integer cents.

    >>> parse_cents("0.10")
    10
    >>> parse_cents("-12.34")
    -1234
    """
    if isinstance(amount, float):
        raise TypeError(
            "refusing float input: construct amounts from strings to avoid "
            "binary floating-point error"
        )
    try:
        d = Decimal(str(amount))
    except InvalidOperation as exc:
        raise ValueError(f"invalid amount: {amount!r}") from exc
    cents = d * _SCALE
    if cents != cents.to_integral_value():
        raise ValueError(f"amount {amount!r} has sub-cent precision")
    return int(cents)


def make_entry(account, debit, credit):
    """Build a ledger entry with debit/credit as integer cents."""
    return {
        'account': account,
        'debit': parse_cents(debit),
        'credit': parse_cents(credit),
    }


def trial_balance(entries):
    totals = {}
    for e in entries:
        a = e['account']
        totals[a] = totals.get(a, 0) + e['debit'] - e['credit']
    return totals


def is_balanced(entries):
    # Exact integer arithmetic: the residual is exactly zero or it isn't.
    return sum(e['debit'] - e['credit'] for e in entries) == 0
